import{_ as s,o as n,c as e,ai as l}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"项目分析与上下文准备","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/coding-sop/03-context-prep.md","filePath":"ai/productivity/coding-sop/03-context-prep.md"}'),p={name:"ai/productivity/coding-sop/03-context-prep.md"};function i(r,a,t,d,c,o){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="项目分析与上下文准备" tabindex="-1">项目分析与上下文准备 <a class="header-anchor" href="#项目分析与上下文准备" aria-label="Permalink to “项目分析与上下文准备”">​</a></h1><blockquote><p>上一章解决了「怎么把任务交代清楚」，本章解决「AI 接到任务后，怎么快速找到该看的地方」。核心方法是分层收敛：先拿项目地图，再定位模块，然后追调用链，最后才读具体文件——而不是让 AI 把整个仓库读一遍。</p></blockquote><h2 id="一、什么时候使用" tabindex="-1">一、什么时候使用 <a class="header-anchor" href="#一、什么时候使用" aria-label="Permalink to “一、什么时候使用”">​</a></h2><p>以下情况必须先做上下文准备，再让 AI 动手：</p><ul><li>第一次进入一个仓库，或接手别人写的项目。</li><li>修改一个自己三个月前写的功能，记忆已经模糊。</li><li>需求涉及「加个字段」「加个接口」但你不确定会波及哪里。</li><li>修复一个涉及多个模块、调用链不清晰的 Bug。</li><li>同一问题改了三次都没改对——通常说明影响范围判断错了。</li></ul><p>以下情况可以跳过：</p><ul><li>改文案、调颜色、改常量值。</li><li>修改自己刚写的、还在上下文里的代码。</li><li>已有明确 Spec 且改动只在一个自包含文件内。</li></ul><p><strong>判断标准：你能不能用一句话说清「改哪里」和「会影响谁」。</strong> 说不出「会影响谁」，就要先做上下文分析。</p><h2 id="二、上下文准备的四层范围" tabindex="-1">二、上下文准备的四层范围 <a class="header-anchor" href="#二、上下文准备的四层范围" aria-label="Permalink to “二、上下文准备的四层范围”">​</a></h2><p>无效扫描的根本原因是<strong>范围没有分层</strong>——AI 拿了整个仓库当上下文，结果里面 95% 与任务无关，真正相关的那几个文件被淹没。</p><p>正确的收敛路径是从外到内、四层递进：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>第 1 层  项目地图      整体结构、模块划分、入口在哪</span></span>
<span class="line"><span>            ↓ 收敛</span></span>
<span class="line"><span>第 2 层  模块地图      本次任务落在哪个模块、涉及哪些子目录</span></span>
<span class="line"><span>            ↓ 收敛</span></span>
<span class="line"><span>第 3 层  调用链        这个模块里，入口 → 服务 → 数据的完整路径</span></span>
<span class="line"><span>            ↓ 收敛</span></span>
<span class="line"><span>第 4 层  相关文件      真正要读、要改的那几个文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>每层的产出是下一层的输入，<strong>上一层没完成不要进下一层</strong>。跳过第 1 层直接搜文件，就会出现「改了 Controller 忘了改 Service」这种漏改；跳过第 3 层直接读文件，就会漏掉异步调用、定时任务和消息消费。</p><h3 id="_2-1-每层的产出与停止条件" tabindex="-1">2.1 每层的产出与停止条件 <a class="header-anchor" href="#_2-1-每层的产出与停止条件" aria-label="Permalink to “2.1 每层的产出与停止条件”">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>产出</th><th>什么时候可以停</th><th>典型耗时</th></tr></thead><tbody><tr><td>项目地图</td><td>模块清单 + 入口清单 + 构建方式</td><td>能说出「这个项目由哪几块组成」</td><td>3–5 分钟</td></tr><tr><td>模块地图</td><td>本次任务涉及的目录与子模块</td><td>能指出「改动落在哪个包里」</td><td>2–3 分钟</td></tr><tr><td>调用链</td><td>从入口到数据层的文件路径</td><td>能画出「请求进来后经过哪几层」</td><td>5–10 分钟</td></tr><tr><td>相关文件</td><td>待读待改文件清单（含不改但受影响的）</td><td>文件清单能逐个说出为什么关心它</td><td>1–2 分钟</td></tr></tbody></table><p><strong>停止条件很重要。</strong> 没有停止条件的分析会一路滑向全仓扫描。</p><h2 id="三、第一层-拿到项目地图" tabindex="-1">三、第一层：拿到项目地图 <a class="header-anchor" href="#三、第一层-拿到项目地图" aria-label="Permalink to “三、第一层：拿到项目地图”">​</a></h2><p>目标是花最短时间知道「这个项目由什么组成、从哪里进入」。</p><h3 id="_3-1-该看什么" tabindex="-1">3.1 该看什么 <a class="header-anchor" href="#_3-1-该看什么" aria-label="Permalink to “3.1 该看什么”">​</a></h3><table tabindex="0"><thead><tr><th>要回答的问题</th><th>去哪里找</th></tr></thead><tbody><tr><td>有几个模块、怎么划分的</td><td><code>pom.xml</code> 的 <code>&lt;modules&gt;</code>、<code>package.json</code> 的 workspaces、<code>settings.gradle</code></td></tr><tr><td>前端入口在哪</td><td><code>src/main.ts</code>、<code>src/App.vue</code>、<code>src/main.js</code></td></tr><tr><td>后端入口在哪</td><td>带 <code>@SpringBootApplication</code> 的类、<code>main</code> 方法</td></tr><tr><td>有哪些环境配置</td><td><code>application*.yml</code>、<code>application*.properties</code>、<code>.env*</code></td></tr><tr><td>怎么构建、怎么跑测试</td><td><code>package.json</code> scripts、<code>pom.xml</code>、<code>Makefile</code>、CI 配置</td></tr><tr><td>哪些目录是产物或依赖</td><td><code>target/</code>、<code>dist/</code>、<code>node_modules/</code>、<code>.git/</code></td></tr></tbody></table><p><strong>明确排除</strong>：<code>node_modules/</code>、<code>target/</code>、<code>dist/</code>、<code>.git/</code>、压缩包、大体积二进制、生成代码目录。这些目录 AI 扫进去只会消耗上下文和出错。</p><h3 id="_3-2-可复制-项目地图扫描提示词" tabindex="-1">3.2 可复制：项目地图扫描提示词 <a class="header-anchor" href="#_3-2-可复制-项目地图扫描提示词" aria-label="Permalink to “3.2 可复制：项目地图扫描提示词”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：产出一份项目地图。不要修改任何文件，不要提改进建议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>背景：我需要了解一个已有项目的整体结构，还没有开始任何开发。</span></span>
<span class="line"><span>目标：让我能回答「这个项目由哪几块组成、从哪里进入、怎么构建」。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 只读分析，不修改任何文件。</span></span>
<span class="line"><span>- 跳过以下目录，不要读取：node_modules、target、dist、build、.git、vendor、依赖目录、生成代码目录。</span></span>
<span class="line"><span>- 优先读取：依赖与构建文件、README、启动入口类、前端入口、配置文件、目录结构。</span></span>
<span class="line"><span>- 不要逐个文件通读，只看入口、配置和目录结构。</span></span>
<span class="line"><span>- 结论必须带证据路径；推断的内容单独放在「待确认」段。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请输出：</span></span>
<span class="line"><span>1. 项目类型与技术栈（后端框架、前端框架、数据库、缓存、消息队列）</span></span>
<span class="line"><span>2. 模块清单（模块名 → 职责一句话 → 入口文件路径）</span></span>
<span class="line"><span>3. 入口清单（启动类、前端入口、可执行脚本）</span></span>
<span class="line"><span>4. 目录结构概览（只列到有业务含义的那一层）</span></span>
<span class="line"><span>5. 构建、启动、测试命令（附来源文件）</span></span>
<span class="line"><span>6. 配置文件清单（路径 → 管什么）</span></span>
<span class="line"><span>7. 外部依赖（数据库、Redis、MQ、第三方接口）</span></span>
<span class="line"><span>8. 本轮未覆盖范围（一句话说明你跳过了什么）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><h2 id="四、第二层-定位相关模块" tabindex="-1">四、第二层：定位相关模块 <a class="header-anchor" href="#四、第二层-定位相关模块" aria-label="Permalink to “四、第二层：定位相关模块”">​</a></h2><p>有了项目地图，下一步是把任务落到具体模块。</p><h3 id="_4-1-定位顺序" tabindex="-1">4.1 定位顺序 <a class="header-anchor" href="#_4-1-定位顺序" aria-label="Permalink to “4.1 定位顺序”">​</a></h3><p>按这个顺序找，先命中先停：</p><ol><li><strong>按业务名词搜</strong>——先搜中文业务词和领域英文词（<code>出库</code>、<code>批次</code>、<code>outbound</code>、<code>batch</code>），业务代码里字段名往往保留业务语义。</li><li><strong>按技术入口搜</strong>——已知要改哪个接口，就从 Controller 或路由定义反查。</li><li><strong>按数据实体搜</strong>——已知涉及哪张表，就搜表名和实体类名。</li><li><strong>按目录结构推</strong>——按项目地图的模块划分，直接推断该落在哪个包里。</li></ol><h3 id="_4-2-多模块项目的额外一步" tabindex="-1">4.2 多模块项目的额外一步 <a class="header-anchor" href="#_4-2-多模块项目的额外一步" aria-label="Permalink to “4.2 多模块项目的额外一步”">​</a></h3><p>Java 多模块项目（<code>ruoyi-admin</code> / <code>ruoyi-system</code> / <code>ruoyi-common</code> / 业务模块）里，必须先确认三件事：</p><ul><li><strong>本模块能否依赖目标模块</strong>——方向错了编译不过，先看 <code>&lt;dependency&gt;</code>。</li><li><strong>公共模块（common）里放什么</strong>——能放通用工具，但放业务逻辑会污染所有模块。</li><li><strong>控制器与实现是否同模块</strong>——有的项目 <code>controller</code> 在 admin 模块、实现放在业务模块的 <code>service</code> 包，改一边不等于改另一边。</li></ul><h3 id="_4-3-可复制-相关模块定位提示词" tabindex="-1">4.3 可复制：相关模块定位提示词 <a class="header-anchor" href="#_4-3-可复制-相关模块定位提示词" aria-label="Permalink to “4.3 可复制：相关模块定位提示词”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：定位本次任务相关的模块和文件，并说明定位依据。不要修改任何文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任务：&lt;本次要做的事，一句话&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 先给模块级判断，再给文件级清单，不要一上来就逐文件读。</span></span>
<span class="line"><span>- 使用搜索定位，不要遍历整个仓库。</span></span>
<span class="line"><span>- 跳过 node_modules、target、dist、build、.git 等目录。</span></span>
<span class="line"><span>- 找不到时明确说「未找到」，并列出你试过的关键词，不要编造路径。</span></span>
<span class="line"><span>- 每个文件都要说明「为什么关心它」（是入口、是实现、是数据、是调用方还是配置）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请输出：</span></span>
<span class="line"><span>1. 任务归属模块（模块名 + 判断依据）</span></span>
<span class="line"><span>2. 相关文件清单（路径 | 角色 | 为什么关心它 | 证据行号）</span></span>
<span class="line"><span>3. 可能受影响的调用方（路径 | 调用方式 | 风险点）</span></span>
<span class="line"><span>4. 不在本次范围内的相邻模块（说明为什么排除）</span></span>
<span class="line"><span>5. 目前仍不确定的部分（需要我提供什么信息）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h2 id="五、第三层-追踪调用链与数据流" tabindex="-1">五、第三层：追踪调用链与数据流 <a class="header-anchor" href="#五、第三层-追踪调用链与数据流" aria-label="Permalink to “五、第三层：追踪调用链与数据流”">​</a></h2><p>这一层是最容易漏、也最容易出问题的地方。</p><h3 id="_5-1-必须覆盖的路径类型" tabindex="-1">5.1 必须覆盖的路径类型 <a class="header-anchor" href="#_5-1-必须覆盖的路径类型" aria-label="Permalink to “5.1 必须覆盖的路径类型”">​</a></h3><p>只跟同步调用链会漏掉大量场景：</p><table tabindex="0"><thead><tr><th>路径类型</th><th>典型位置</th><th>漏掉的后果</th></tr></thead><tbody><tr><td>同步调用</td><td>Controller → Service → Mapper</td><td>相对少见漏</td></tr><tr><td>前端调用</td><td>Vue 页面 → API 定义 → 后端接口</td><td>前端传参变了后端没同步</td></tr><tr><td>异步任务</td><td><code>@Scheduled</code>、<code>@Async</code>、线程池</td><td>定时跑的任务用的是旧逻辑</td></tr><tr><td>消息消费</td><td>MQ 消费者、事件监听器</td><td>消息格式改了消费端没改</td></tr><tr><td>配置驱动</td><td>开关、字典、配置表</td><td>功能被开关关着，测不出来</td></tr><tr><td>反射 / 动态 SQL</td><td>MyBatis XML、动态路由</td><td>改的 SQL 根本没人调用</td></tr></tbody></table><h3 id="_5-2-追踪的终点" tabindex="-1">5.2 追踪的终点 <a class="header-anchor" href="#_5-2-追踪的终点" aria-label="Permalink to “5.2 追踪的终点”">​</a></h3><p>链条要一直追到<strong>数据落点</strong>才算完：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>接口入口 → 参数校验 → 业务服务 → 领域规则 → 数据访问 → 表/SQL</span></span>
<span class="line"><span>                                    ↓</span></span>
<span class="line"><span>                              事务边界在哪</span></span>
<span class="line"><span>                                    ↓</span></span>
<span class="line"><span>                              异常怎么抛出、怎么被处理</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>三个必须回答的问题：<strong>数据改在哪张表</strong>、<strong>事务边界在哪</strong>、<strong>异常最终怎么处理</strong>。</p><h3 id="_5-3-可复制-调用链追踪提示词" tabindex="-1">5.3 可复制：调用链追踪提示词 <a class="header-anchor" href="#_5-3-可复制-调用链追踪提示词" aria-label="Permalink to “5.3 可复制：调用链追踪提示词”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：追踪一条完整调用链，输出链路和数据流。不要修改任何文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>入口：&lt;入口描述，如「POST /api/mes/work-orders/{id}/report」或「前端页面 X 的提交按钮」&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 从入口一直追到数据落点，中间不要停。</span></span>
<span class="line"><span>- 必须覆盖并说明：同步调用、异步任务（定时/线程池）、消息消费、配置开关、动态 SQL 拼装。</span></span>
<span class="line"><span>- 每一步给出「文件路径:行号」和「方法名」。</span></span>
<span class="line"><span>- 找出事务边界（@Transactional 的开始与结束位置）和异常处理位置。</span></span>
<span class="line"><span>- 指出这条链上所有会读写的表。</span></span>
<span class="line"><span>- 没有找到的环节明确标「未找到」，不要跳过不提。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请输出：</span></span>
<span class="line"><span>1. 调用链总览（一行一步的链路图）</span></span>
<span class="line"><span>2. 逐层明细（层 | 文件:行号 | 方法 | 职责 | 数据变化）</span></span>
<span class="line"><span>3. 涉及的数据表（表名 | 读/写 | 关键字段）</span></span>
<span class="line"><span>4. 事务边界与异常处理</span></span>
<span class="line"><span>5. 隐藏路径（异步/消息/定时/动态 SQL）</span></span>
<span class="line"><span>6. 这条链上最容易出问题的 3 个位置及原因</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="六、第四层-核对数据库、接口与外部依赖" tabindex="-1">六、第四层：核对数据库、接口与外部依赖 <a class="header-anchor" href="#六、第四层-核对数据库、接口与外部依赖" aria-label="Permalink to “六、第四层：核对数据库、接口与外部依赖”">​</a></h2><p>分析不能只看代码。有三处「代码里看不到」的东西必须专门核对。</p><h3 id="_6-1-数据库结构" tabindex="-1">6.1 数据库结构 <a class="header-anchor" href="#_6-1-数据库结构" aria-label="Permalink to “6.1 数据库结构”">​</a></h3><ul><li>表结构以<strong>迁移脚本或实际库</strong>为准，不要以实体类为准——实体类可能漏字段、可能与线上不一致。</li><li>看索引：这次改动如果加了查询条件，是否命中索引；有没有唯一约束会被新逻辑破坏。</li><li>看约束：外键、唯一键、非空约束，新代码是否违反。</li><li>看数据量级：一张几万行的表和一张几十万行的表，加个查询条件的后果完全不同。</li></ul><p><strong>核对方式</strong>：优先读 <code>resources/db/migration/</code> 或 <code>sql/</code> 目录下的迁移脚本；能连测试库则直接查 <code>information_schema</code>，但<strong>只读、且先确认是测试库</strong>。</p><h3 id="_6-2-接口契约" tabindex="-1">6.2 接口契约 <a class="header-anchor" href="#_6-2-接口契约" aria-label="Permalink to “6.2 接口契约”">​</a></h3><p>前端与后端是一对，改一边必须看另一边：</p><ul><li>前端 API 定义文件（<code>api/*.ts</code>、<code>src/api/**</code>）里的路径、参数、返回结构。</li><li>后端 Controller 的入参 DTO、返回包装类、错误码。</li><li>是否有接口文档、是否有契约测试。</li></ul><p>常见问题：前端传 <code>status</code> 字符串，后端收的是枚举数字；前端返回体读 <code>data.list</code>，后端改成了 <code>data.records</code>；错误码从 400 改成 409，前端只按 <code>body.code</code> 判断。</p><h3 id="_6-3-外部依赖" tabindex="-1">6.3 外部依赖 <a class="header-anchor" href="#_6-3-外部依赖" aria-label="Permalink to “6.3 外部依赖”">​</a></h3><ul><li>Redis 缓存：改了数据但不失效缓存，是「代码没问题但功能不对」的典型原因。</li><li>MQ：消息体格式、幂等键、重试与死信策略。</li><li>第三方接口：签名方式、超时、重试、限流，失败时是降级还是抛错。</li></ul><h3 id="_6-4-可复制-依赖与影响面核对提示词" tabindex="-1">6.4 可复制：依赖与影响面核对提示词 <a class="header-anchor" href="#_6-4-可复制-依赖与影响面核对提示词" aria-label="Permalink to “6.4 可复制：依赖与影响面核对提示词”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：核对本次改动会波及的数据库、接口、缓存和外部依赖。不要修改任何文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改动点：&lt;文件:行号 + 改了什么&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 数据库结构以迁移脚本或实际库为准，实体类只作参考。</span></span>
<span class="line"><span>- 只读核对，不要执行任何写操作，不要连接生产库。</span></span>
<span class="line"><span>- 缓存、消息、第三方接口都要覆盖，即使本次没直接改到——间接依赖必须指出。</span></span>
<span class="line"><span>- 每条结论给出证据来源（文件路径、SQL 结果或配置项）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请输出：</span></span>
<span class="line"><span>1. 直接影响（被修改的表、接口、缓存键、消息体）</span></span>
<span class="line"><span>2. 间接影响（调用方、被缓存的数据、定时任务、报表统计）</span></span>
<span class="line"><span>3. 数据一致性风险（缓存未失效、索引缺失、约束冲突、并发覆盖）</span></span>
<span class="line"><span>4. 接口兼容性风险（字段增删改、状态码变化、返回结构变化）</span></span>
<span class="line"><span>5. 需要人工确认的事项（列出具体问题，不给猜测结论）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h2 id="七、影响范围判断" tabindex="-1">七、影响范围判断 <a class="header-anchor" href="#七、影响范围判断" aria-label="Permalink to “七、影响范围判断”">​</a></h2><p>判断影响范围不是靠感觉，而是靠四类证据。</p><table tabindex="0"><thead><tr><th>证据类型</th><th>怎么查</th><th>说明什么</th></tr></thead><tbody><tr><td>反向调用</td><td>全仓搜方法名、接口路径、字段名</td><td>谁会受影响</td></tr><tr><td>数据落点</td><td>追踪到表，看谁写这张表</td><td>哪些功能依赖这张表</td></tr><tr><td>配置开关</td><td>搜开关名、字典项、特性开关</td><td>功能是否被条件启用</td></tr><tr><td>测试覆盖</td><td>看有没有对应测试文件</td><td>改动是否有回归保护</td></tr></tbody></table><p><strong>结论要写成清单，不能只写一句话。</strong> 合格的输出形如：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>本次改动影响 7 个文件：</span></span>
<span class="line"><span>- 直接修改：WorkOrderService.java、WorkOrderController.java、mes.ts</span></span>
<span class="line"><span>- 必须同步：WorkOrderDTO.java（新增字段）、TraceView.vue（展示新字段）</span></span>
<span class="line"><span>- 需要回归：ReportOperationView.vue（依赖同一接口返回结构）</span></span>
<span class="line"><span>- 可能受影响但不改：MesScheduler.java（每日统计读同一张表）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="八、上下文是否足够的判断标准" tabindex="-1">八、上下文是否足够的判断标准 <a class="header-anchor" href="#八、上下文是否足够的判断标准" aria-label="Permalink to “八、上下文是否足够的判断标准”">​</a></h2><p>在动手改代码前，用这五个问题自检：</p><ol><li><strong>我知道要改哪几个文件吗？</strong> 说不出来就是上下文不足。</li><li><strong>我知道改完之后谁会受影响吗？</strong> 只知道改哪、不知道影响谁，不够。</li><li><strong>我知道这次改动涉及哪张表、哪个接口吗？</strong> 不清楚数据落点，不够。</li><li><strong>我知道现有实现为什么这么写吗？</strong> 不明原因就容易把有意设计当冗余删掉。</li><li><strong>我知道哪些地方不能碰吗？</strong> 没有禁改区概念，就容易顺手重构。</li></ol><p>五问中有两条答不上来，回到上一层补，不要带着缺口开始改代码。</p><h2 id="九、复用已有项目知识-不要重复扫描" tabindex="-1">九、复用已有项目知识，不要重复扫描 <a class="header-anchor" href="#九、复用已有项目知识-不要重复扫描" aria-label="Permalink to “九、复用已有项目知识，不要重复扫描”">​</a></h2><p>如果第 01 章的接入工作已经做过，项目里应该已经有认知资料。<strong>先读它，再扫描。</strong></p><table tabindex="0"><thead><tr><th>已有资料</th><th>复用方式</th><th>不要重复做的事</th></tr></thead><tbody><tr><td>项目认知报告</td><td>直接读第 3、4、5 节（目录、规则、数据接口）</td><td>重新扫目录结构</td></tr><tr><td>项目规则文件</td><td>直接作为约束，不再重复交代</td><td>每次会话重新贴约束</td></tr><tr><td>模块地图文档</td><td>直接定位模块</td><td>重新搜入口</td></tr><tr><td>gotchas 记录</td><td>直接读，避免重复踩坑</td><td>重新发现已知坑</td></tr></tbody></table><p>如果接入资料与当前代码不一致（有人改了代码没更新文档），以<strong>代码</strong>为准，并把差异记下来——这本身是一条值得更新的经验。</p><h2 id="十、常见错误" tabindex="-1">十、常见错误 <a class="header-anchor" href="#十、常见错误" aria-label="Permalink to “十、常见错误”">​</a></h2><h3 id="错误-1-一次性让-ai-读整个仓库" tabindex="-1">错误 1：一次性让 AI 读整个仓库 <a class="header-anchor" href="#错误-1-一次性让-ai-读整个仓库" aria-label="Permalink to “错误 1：一次性让 AI 读整个仓库”">​</a></h3><p>问题：上下文被无关代码占满，关键信息反而被稀释；分析结果看起来面面俱到，实际不可用。</p><p>正确做法：严格按四层收敛，每层有停止条件，输出进入下一层前先确认。</p><h3 id="错误-2-只跟同步调用链" tabindex="-1">错误 2：只跟同步调用链 <a class="header-anchor" href="#错误-2-只跟同步调用链" aria-label="Permalink to “错误 2：只跟同步调用链”">​</a></h3><p>问题：漏掉定时任务、消息消费、配置开关，改了主流程但旧路径还在跑。</p><p>正确做法：把六类路径逐条确认，答不上来的标为待确认。</p><h3 id="错误-3-以实体类推断数据库结构" tabindex="-1">错误 3：以实体类推断数据库结构 <a class="header-anchor" href="#错误-3-以实体类推断数据库结构" aria-label="Permalink to “错误 3：以实体类推断数据库结构”">​</a></h3><p>问题：实体类漏字段、加了 <code>@TableField(exist = false)</code> 的非持久化字段，读到假的表结构。</p><p>正确做法：以迁移脚本或实际库为准，实体类只作参考。</p><h3 id="错误-4-把「看懂了」当成「验证过了」" tabindex="-1">错误 4：把「看懂了」当成「验证过了」 <a class="header-anchor" href="#错误-4-把「看懂了」当成「验证过了」" aria-label="Permalink to “错误 4：把「看懂了」当成「验证过了」”">​</a></h3><p>问题：AI 读完代码说「已理解业务逻辑」，实际是从命名和注释推测的。</p><p>正确做法：所有理解必须带证据路径；靠推测得出的业务规则一律标为待确认，不能当事实往下走。</p><h3 id="错误-5-影响范围只写一句话" tabindex="-1">错误 5：影响范围只写一句话 <a class="header-anchor" href="#错误-5-影响范围只写一句话" aria-label="Permalink to “错误 5：影响范围只写一句话”">​</a></h3><p>问题：「影响列表查询相关逻辑」这种描述无法作为核对清单，改漏了也发现不了。</p><p>正确做法：输出逐文件清单，每个文件标明角色和原因，区分「必须同步」与「需要回归」。</p><h2 id="十一、本章完成检查" tabindex="-1">十一、本章完成检查 <a class="header-anchor" href="#十一、本章完成检查" aria-label="Permalink to “十一、本章完成检查”">​</a></h2><p>开始写代码前，确认下面这些都已经落到纸上：</p><ul><li>[ ] 有一份项目地图（模块、入口、构建命令），新接手项目时至少扫过一次。</li><li>[ ] 明确本次任务落在哪个模块、涉及哪些子目录。</li><li>[ ] 至少追出一条完整调用链，从入口到数据落点。</li><li>[ ] 确认了同步、异步、消息、定时、配置开关、动态 SQL 六类路径中没有未覆盖的。</li><li>[ ] 核对了数据库结构来源（迁移脚本或实际库）。</li><li>[ ] 核对了前端 API 定义与后端接口契约。</li><li>[ ] 确认了 Redis 缓存、MQ、第三方接口的间接影响。</li><li>[ ] 有一份逐文件的影响清单，标明直接修改 / 必须同步 / 需要回归。</li><li>[ ] 五问自检没有两条以上答不上来。</li><li>[ ] 已有项目资料被复用，没有重复扫描。</li></ul><p>下一章解决更靠前的问题：<strong>上下文准备完之后，怎么形成技术方案，并把一个大任务拆成 AI 可以连续执行的步骤。</strong></p><p><a href="/my-vitepress-site/ai/productivity/coding-sop/04-plan-decompose.html">进入第 04 章</a></p>`,91)])])}const u=s(p,[["render",i]]);export{h as __pageData,u as default};
